func (t *CommandNode) ReadFrom(r io.Reader) (totalBytes int64, err error) {
	var bytesRead int64
	bytesRead, err = t.Flags.ReadFrom(r)
	totalBytes += bytesRead
	if err != nil {
		return totalBytes, errors.Wrap(err, "failed to read field Flags")
	}
	bytesRead, err = t.Children.ReadFrom(r)
	totalBytes += bytesRead
	if err != nil {
		return totalBytes, errors.Wrap(err, "failed to read field Children")
	}
	// Switch field RedirectNode based on flags/has_redirect_node
	// Check bitflag member
	compareValueRedirectNode := fmt.Sprintf("%v", t.Flags.HasRedirectNode)

	switch compareValueRedirectNode {
	case "1":
		var val pk.VarInt
		bytesRead, err = val.ReadFrom(r)
		totalBytes += bytesRead
		if err != nil {
			return totalBytes, errors.Wrap(err, "failed to read switch field RedirectNode case 1")
		}
		t.RedirectNode = &val
	default:
		// Void case - no data to read
		var __void models.Void
		bytesRead, err = __void.ReadFrom(r)
		totalBytes += bytesRead
		if err != nil {
			return totalBytes, errors.Wrap(err, "failed to read void switch field RedirectNode default case")
		}
		t.RedirectNode = &__void
	}

	// Switch field ExtraNodeData based on flags/command_node_type
	// Check bitflag member
	compareValueExtraNodeData := fmt.Sprintf("%v", t.Flags.CommandNodeType)

	switch compareValueExtraNodeData {
	case "0":
		// Void case - no data to read
		var __void models.Void
		bytesRead, err = __void.ReadFrom(r)
		totalBytes += bytesRead
		if err != nil {
			return totalBytes, errors.Wrap(err, "failed to read void switch field ExtraNodeData case 0")
		}
		t.ExtraNodeData = &__void
	case "1":
		var val CommandNodeExtraNodeData1
		bytesRead, err = val.ReadFrom(r)
		totalBytes += bytesRead
		if err != nil {
			return totalBytes, errors.Wrap(err, "failed to read switch field ExtraNodeData case 1")
		}
		t.ExtraNodeData = &val
	case "2":
		var val CommandNodeExtraNodeData2
		// Type requires parent context - build context from current container fields
		ctx_ExtraNodeData_2 := models.NewParentContext()
		ctx_ExtraNodeData_2.SetField("flags/has_custom_suggestions", t.Flags.HasCustomSuggestions)
		bytesRead, err = val.ReadFromWithParentContext(r, ctx_ExtraNodeData_2)
		totalBytes += bytesRead
		if err != nil {
			return totalBytes, errors.Wrap(err, "failed to read switch field ExtraNodeData case 2")
		}
		t.ExtraNodeData = &val
	default:
		// No explicit default; treat as void (no data)
		// Per minecraft.wiki protocol docs: "If properties for parser are not specified, then this parser has no properties"
		// Using Buffer.ReadFrom() here would call io.ReadAll() and consume ALL remaining data, breaking array parsing
		var __void models.Void
		bytesRead, err = __void.ReadFrom(r)
		totalBytes += bytesRead
		if err != nil {
			return totalBytes, errors.Wrap(err, "failed to read switch field ExtraNodeData default void case")
		}
		t.ExtraNodeData = &__void
	}

	return totalBytes, nil
}

func (t CommandNode) WriteTo(w io.Writer) (totalBytes int64, err error) {
	var bytesWritten int64

	defer func() {
		log.Printf("[CommandNode.WriteTo] totalBytes: %d err: %#v", totalBytes, err)
	}()
	bytesWritten, err = t.Flags.WriteTo(w)
	totalBytes += bytesWritten
	if err != nil {
		return totalBytes, err
	}
	bytesWritten, err = t.Children.WriteTo(w)
	totalBytes += bytesWritten
	if err != nil {
		return totalBytes, err
	}
	// Switch field RedirectNode based on flags/has_redirect_node
	if t.RedirectNode != nil {
		// Write switch field value if it implements WriteTo
		if writer, ok := t.RedirectNode.(interface {
			WriteTo(io.Writer) (int64, error)
		}); ok {
			bytesWritten, err = writer.WriteTo(w)
			totalBytes += bytesWritten
			if err != nil {
				return totalBytes, err
			}
		} else {
			// Not a void case and doesn't implement WriteTo
			return totalBytes, fmt.Errorf("switch field RedirectNode value does not implement WriteTo: %T", t.RedirectNode)
		}
	}
	// Switch field ExtraNodeData based on flags/command_node_type
	if t.ExtraNodeData != nil {
		// Write switch field value if it implements WriteTo
		if writer, ok := t.ExtraNodeData.(interface {
			WriteTo(io.Writer) (int64, error)
		}); ok {
			bytesWritten, err = writer.WriteTo(w)
			totalBytes += bytesWritten
			if err != nil {
				return totalBytes, err
			}
		} else {
			// Not a void case and doesn't implement WriteTo
			return totalBytes, fmt.Errorf("switch field ExtraNodeData value does not implement WriteTo: %T", t.ExtraNodeData)
		}
	}
	return totalBytes, nil
}
